few_shot_examples:
Request: Add Python as a skill to his MSU research experience -> existing = db.query("SELECT * FROM skills WHERE name = 'Python' AND experience_id = (SELECT experience_id FROM experiences WHERE name = 'MSU Research')")
if existing:
    outcome = "Element already exists in the skills table."
else:
    db.insertRows('skills', ['experience_id', 'name', 'skill_level'], ["(SELECT experience_id FROM experiences WHERE name = 'MSU Research')", 'Python', 5])
    outcome = "New Python added to the skills table."
